"""Shared, scoped styling for scientific plots generated by the project.

The palette is Amazon-inspired (squid ink + Amazon orange, with validated companion hues); its
roles, rules and validator live in the `amazon-colors` skill. Change a value here only after
re-running `.agents/skills/amazon-colors/scripts/validate_palette.py`.
"""

from __future__ import annotations

from functools import wraps

import matplotlib
from cycler import cycler

# ---- brand anchors ----------------------------------------------------------------------------
SQUID_INK = "#232F3E"
AMAZON_ORANGE = "#FF9900"   # fills, highlight bands, dark-mode accents; too light for marks on white
NAV_INK = "#131921"

# ---- surfaces and text, per mode --------------------------------------------------------------
SURFACE = {"light": "#FFFFFF", "dark": "#161D26"}
TEXT = {"light": SQUID_INK, "dark": "#F2F4F6"}
MUTED = {"light": "#545B64", "dark": "#AAB7B8"}
BORDER = {"light": "#D5D9D9", "dark": "#37475A"}
REFERENCE = {"light": "#879596", "dark": "#5A6B7E"}  # reference/context lines, >= 3:1 on surface

INK = TEXT["light"]
MUTED_INK = MUTED["light"]
GRID = BORDER["light"]
REFERENCE_LINE = REFERENCE["light"]
TINT = "#F0F2F2"          # table headers, panels
NOTICE_TINT = "#FFF4E5"   # callout background, paired with an AMAZON_ORANGE rule
LINK = "#007185"

# ---- categorical: fixed order, never cycled past eight ---------------------------------------
# Same hue family per slot in both modes: blue, orange, magenta, gold, teal, red, purple, green.
CATEGORICAL = {
    "light": ("#146EB4", "#B75F0B", "#AE1A69", "#99740E",
              "#0698A4", "#B71A18", "#6F41C1", "#087736"),
    "dark": ("#007ED4", "#C9690C", "#CA3A80", "#A87F09",
             "#0698A4", "#D33C33", "#855BDC", "#119245"),
}
CATEGORICAL_8 = CATEGORICAL["light"]
PRIMARY = CATEGORICAL_8[0]  # the proposed method / the one series that matters
ACCENT = CATEGORICAL_8[1]   # mark-weight orange for a focal series, loss, or highlight

# ---- sequential, diverging, status -----------------------------------------------------------
SEQUENTIAL_BLUE = ("#E3F0FE", "#B3D9FF", "#7ABDFE", "#379DF6", "#007ED4", "#0160A4", "#014477")
SEQUENTIAL_ORANGE = ("#FEEFE2", "#FED1AA", "#FEAC5F", "#F08B00", "#C97405", "#A05B01", "#794402")
# Negative (blue) -> neutral -> positive (orange). Reverse it when the "bad" side is negative.
DIVERGING = ("#005896", "#599DDF", "#EFF2F5", "#FDA856", "#B85F05")
STATUS = {
    "light": {"ok": "#067D62", "warning": "#8A5300", "critical": "#B12704", "info": LINK},
    "dark": {"ok": "#4CC08F", "warning": "#FFB84D", "critical": "#FF7A6B", "info": "#4DB8C9"},
}

FOLD_COLORS = CATEGORICAL_8[:6]
LINE_STYLES = ("-", "--", ":", "-.")
MARKERS = ("o", "s", "^", "D", "P", "X")

EXPORT_DPI = 300
EMBED_DPI = 160

PLOT_RC = {
    "axes.axisbelow": True,
    "axes.edgecolor": GRID,
    "axes.facecolor": "white",
    "axes.grid": False,
    "axes.labelcolor": INK,
    "axes.prop_cycle": cycler(color=CATEGORICAL_8),
    "axes.spines.right": False,
    "axes.spines.top": False,
    "axes.titlecolor": INK,
    "axes.titleweight": "semibold",
    "figure.facecolor": "white",
    "font.family": "sans-serif",
    "grid.alpha": 0.6,
    "grid.color": GRID,
    "grid.linewidth": 0.7,
    "image.cmap": "amazon_blue",
    "legend.frameon": False,
    "savefig.facecolor": "white",
    "text.color": INK,
    "xtick.color": MUTED_INK,
    "ytick.color": MUTED_INK,
}

METRIC_COLORS = {
    "loss": ACCENT,
    "dice": PRIMARY,
    "iou": CATEGORICAL_8[4],
    "balanced_accuracy": PRIMARY,
    "macro_f1": CATEGORICAL_8[4],
    "accuracy": MUTED_INK,
    "auc": PRIMARY,
    "auc_ovr_macro": PRIMARY,
}


def _register_colormaps():
    from matplotlib.colors import LinearSegmentedColormap

    for name, colors in (("amazon_blue", SEQUENTIAL_BLUE), ("amazon_orange", SEQUENTIAL_ORANGE),
                         ("amazon_diverging", DIVERGING)):
        for suffix, ordered in (("", colors), ("_r", colors[::-1])):
            if name + suffix not in matplotlib.colormaps:
                matplotlib.colormaps.register(
                    LinearSegmentedColormap.from_list(name + suffix, list(ordered)))


_register_colormaps()


def colormap(name="blue"):
    """Return the registered `amazon_<name>` colormap (blue, orange, diverging; `_r` reverses)."""
    return matplotlib.colormaps[f"amazon_{name}"]


def with_plot_style(function):
    """Run one plot builder in an rc context without mutating global Matplotlib state."""
    @wraps(function)
    def wrapped(*args, **kwargs):
        with matplotlib.rc_context(PLOT_RC):
            return function(*args, **kwargs)
    return wrapped


def categorical_color(index):
    return CATEGORICAL_8[int(index) % len(CATEGORICAL_8)]


def fold_style(index):
    index = int(index)
    return {
        "color": FOLD_COLORS[index % len(FOLD_COLORS)],
        "linestyle": LINE_STYLES[index % len(LINE_STYLES)],
        "marker": MARKERS[index % len(MARKERS)],
    }


def metric_color(metric_name, fallback_index=0):
    name = str(metric_name).lower()
    if name in METRIC_COLORS:
        return METRIC_COLORS[name]
    if "loss" in name:
        return ACCENT
    if "auc" in name:
        return METRIC_COLORS["auc"]
    return categorical_color(fallback_index)


def setup_color(label, fallback_index=0):
    """Keep experimental setup colors stable across reports and plot orderings."""
    name = str(label).lower().replace("_", "-")
    if "local" in name or "standalone" in name:
        return MUTED_INK
    if "central" in name:
        return ACCENT
    if "federat" in name or "fedper" in name:
        return PRIMARY
    return categorical_color(fallback_index)


def split_style(split, phase="", fallback_index=0):
    """Differentiate training/evaluation traces without relying on color alone."""
    split = str(split).lower()
    phase = str(phase).lower()
    if split in {"val", "validation"}:
        return {"linestyle": "-", "marker": "o"}
    if split == "test":
        return {"linestyle": ":", "marker": "^"}
    if "step" in phase:
        return {"linestyle": "--", "marker": None}
    if split == "train":
        return {"linestyle": "--", "marker": "s"}
    return {
        "linestyle": LINE_STYLES[int(fallback_index) % len(LINE_STYLES)],
        "marker": MARKERS[int(fallback_index) % len(MARKERS)],
    }


def style_axis(axis, *, grid_axis="y"):
    axis.set_axisbelow(True)
    axis.grid(True, axis=grid_axis, color=GRID, alpha=0.6, linewidth=0.7)
    axis.spines["top"].set_visible(False)
    axis.spines["right"].set_visible(False)
    axis.spines["left"].set_color(GRID)
    axis.spines["bottom"].set_color(GRID)

